-- The home screen's verse rotation: 183 verses, one for each day, cycling.
--
-- Korean is 개역한글판 (대한성서공회), English is the World English Bible (public domain), and
-- Khmer is the 1954 translation (The Bible Society in Cambodia). The verse list and its order
-- come from verses/daily-verses.refs.json; the text was fetched by scripts/fill-verses.mjs and
-- is stored exactly as the publishers print it.
--
-- 00107 seeded one verse per language so the card was never blank. Those three rows are kept
-- in a backup table first, then removed — 시편 27:1 is not in this list, and sort_order 1 is
-- needed by day 1.

CREATE TABLE public.daily_verses_backup_00108 AS
  SELECT * FROM public.daily_verses;

DELETE FROM public.daily_verses;

